// Помощники стартового теста (#c121d3, #a0f00f): создание QA-ребёнка, передача устройства, прохождение чтения без голоса и письма.
// Без waitForTimeout / networkidle: только ожидание состояния через expect(...) / waitForURL / waitForResponse.
// Селекторы с пометкой TODO verify selector взяты из заметок QA (research/*.md), в браузере при записи не проверялись.
import { expect, Browser, BrowserContext, BrowserContextOptions, Page, TestInfo } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

export const SUBMIT_WRITING_RPC = '/rest/v1/rpc/submit_placement_writing';
export const CONFIDENT_TEXT = 'הילד קורא ספר יפה בבית';

/** Имя тестового ребёнка: QA-AUTO- + 6 латинских букв, без цифр (C3 проверяется на отсутствие цифр). */
export function qaChildName(): string {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  let s = '';
  for (let i = 0; i < 6; i++) s += letters[Math.floor(Math.random() * letters.length)];
  return `QA-AUTO-${s}`;
}

/** Запись для ручной чистки (удаление профиля требует пароль родителя — делает пользователь). */
export function annotateCleanup(testInfo: TestInfo, childName: string, childId: string) {
  testInfo.annotations.push({
    type: 'cleanup',
    description: `child ${childName} ${childId} — удалить вручную (нужен пароль родителя)`,
  });
}

/**
 * Окно с сохранённой сессией вне фикстуры asUser — для общих (serial) сценариев, где одна страница живёт
 * через несколько тестов (beforeAll). Параметры окна — из текущего проекта, как в fixtures.ts.
 */
export async function openSharedUserPage(browser: Browser, testInfo: TestInfo, id: string): Promise<{ context: BrowserContext; page: Page }> {
  const storageState = path.resolve(__dirname, '../../../auth', `${id}.json`);
  if (!fs.existsSync(storageState)) {
    throw new Error(`Нет сессии «${id}» (.qa/auth/${id}.json). Запусти npm run qa-login или qa-login:manual -- ${id}`);
  }
  const keys = ['baseURL', 'locale', 'viewport', 'userAgent', 'deviceScaleFactor', 'isMobile', 'hasTouch', 'timezoneId'] as const;
  const projectUse = testInfo.project.use as Record<string, unknown>;
  const options: BrowserContextOptions = {};
  for (const k of keys) if (projectUse[k] !== undefined) (options as Record<string, unknown>)[k] = projectUse[k];
  const context = await browser.newContext({ ...options, storageState });
  return { context, page: await context.newPage() };
}

/**
 * Создать профиль ребёнка на /children/new (зона родителя). Возвращает id ребёнка.
 * id берётся из ответа сервера на создание (Supabase REST, POST в children), запасной вариант — из адреса.
 */
export async function createChild(page: Page, name: string, birthYear = '2018'): Promise<string> {
  await page.goto('/children/new');
  await expect(page.getByText('פרופיל ילד חדש')).toBeVisible();
  await page.getByLabel('שם או כינוי').fill(name); // TODO verify selector (поле «שם או כינוי» — из плана, label не проверен)
  await page.getByLabel(/שנת לידה/).fill(birthYear); // TODO verify selector (label «שנת לידה» — из реджекта #f23704)

  // TODO verify selector: таблица `children` и форма ответа (return=representation) не проверены.
  const created = page.waitForResponse(
    (r) => r.request().method() === 'POST' && /\/rest\/v1\/children(\?|$)/.test(r.url()),
  );
  await page.getByRole('button', { name: /שמיר|שמור/ }).click(); // TODO verify selector (текст кнопки сохранения)
  const resp = await created;
  expect(resp.ok(), `создание профиля: HTTP ${resp.status()}`).toBeTruthy();

  let id: string | undefined;
  try {
    const body = await resp.json();
    id = Array.isArray(body) ? body[0]?.id : body?.id;
  } catch {
    /* тело может быть пустым (return=minimal) — берём id из адреса ниже */
  }
  if (!id) {
    await page.waitForURL(/\/children\/[0-9a-f-]{36}/);
    id = page.url().match(/\/children\/([0-9a-f-]{36})/)?.[1];
  }
  if (!id) throw new Error('Не удалось получить id созданного ребёнка (ни из ответа сервера, ни из адреса)');
  return id;
}

/** Передать устройство ребёнку и начать стартовый тест (C1 «מבחן פתיחה» → «מתחילים!»). */
export async function startPlacementAsChild(page: Page, childId: string, childName: string) {
  await page.goto(`/children/${childId}/handover`);
  await page.getByRole('button', { name: `${childName}, בואו נתחיל!` }).click(); // текст из #14e9a4 («QA-Base, בואו נתחיל!»)
  await page.getByRole('button', { name: 'מתחילים!', exact: true }).click(); // C1 (#8bf5a8); TODO verify selector
}

export type ReadingAnswer = 'קל' | 'לא בטוח/ה';

/**
 * Чтение без микрофона: «קראתי!» → карточка «לא שומעים אותך כרגע» → «לנסות שוב» → «קראתי!» → «איך היה?» → ответ.
 * Цикл до появления поля письма (data-testid=writing-input). Тест адаптивный — число текстов заранее не известно.
 */
export async function passReading(page: Page, answer: ReadingAnswer, maxSteps = 40) {
  const writing = page.getByTestId('writing-input');
  const read = page.getByRole('button', { name: 'קראתי!', exact: true });
  const retry = page.getByRole('button', { name: 'לנסות שוב', exact: true });
  const howWasIt = page.getByText('איך היה?');
  const rate = page.getByRole('button', { name: answer, exact: true });

  for (let step = 0; step < maxSteps; step++) {
    await expect(writing.or(howWasIt).or(retry).or(read).first()).toBeVisible({ timeout: 30_000 });
    if (await writing.isVisible()) return;

    if (await howWasIt.isVisible()) {
      await rate.click();
      // Ждём, пока уйдёт вопрос самооценки (следующий текст или письмо).
      await expect(howWasIt).toBeHidden({ timeout: 30_000 });
    } else if (await retry.isVisible()) {
      await retry.click();
      await expect(writing.or(howWasIt).or(read).first()).toBeVisible({ timeout: 30_000 });
    } else {
      await read.click();
      await expect(writing.or(howWasIt).or(retry).first()).toBeVisible({ timeout: 30_000 });
    }
  }
  throw new Error(`Чтение не закончилось за ${maxSteps} шагов (поле письма writing-input так и не появилось)`);
}

export type WritingMode = 'confident' | 'unsure';

export interface WritingResult {
  /** Сколько раз за письмо показали «בואו ננסה עוד פעם!» (неуверенный ответ). */
  retryPrompts: number;
  /** Сколько раз отправлено (подтверждённых «שלחתי!»). */
  submits: number;
}

/**
 * Письмо до экрана C3: в каждое задание ввести текст → page.once('dialog', accept) → «שלחתי!» →
 * дождаться ответа submit_placement_writing и ухода «מעבדים…». Уверенно — осмысленный иврит, неуверенно — «abc»
 * (первая попытка → «בואו ננסה עוד פעם!», вторая сохраняется как неуверенный ответ).
 */
export async function passWriting(page: Page, mode: WritingMode, maxSteps = 40): Promise<WritingResult> {
  const input = page.getByTestId('writing-input');
  const c3 = page.getByText(/^כל הכבוד, /);
  const tryAgain = page.getByText('בואו ננסה עוד פעם!');
  const processing = page.getByText('מעבדים…');
  const send = page.getByRole('button', { name: 'שלחתי!', exact: true });
  const result: WritingResult = { retryPrompts: 0, submits: 0 };

  for (let step = 0; step < maxSteps; step++) {
    await expect(input.or(c3).first()).toBeVisible({ timeout: 60_000 });
    if (await c3.isVisible()) return result;

    await input.fill(mode === 'confident' ? CONFIDENT_TEXT : 'abc');
    page.once('dialog', (d) => d.accept()); // window.confirm «לשלוח לבנג׳י?…» — по умолчанию Playwright его отклоняет
    const submitted = page.waitForResponse((r) => r.url().includes(SUBMIT_WRITING_RPC), { timeout: 60_000 });
    await send.click();
    const resp = await submitted;
    expect(resp.ok(), `submit_placement_writing: HTTP ${resp.status()}`).toBeTruthy();
    result.submits++;
    await expect(processing).toBeHidden({ timeout: 60_000 });
    if (await tryAgain.isVisible()) result.retryPrompts++;
  }
  throw new Error(`Письмо не закончилось за ${maxSteps} шагов (экран C3 «כל הכבוד, …!» не появился)`);
}

/** Полное прохождение: чтение (ответ самооценки) + письмо (уверенно / неуверенно) до C3. */
export async function passPlacement(page: Page, opts: { reading: ReadingAnswer; writing: WritingMode }): Promise<WritingResult> {
  await passReading(page, opts.reading);
  return passWriting(page, opts.writing);
}

/** Строки уровней в профиле ребёнка у родителя (/children/<id>). */
export function levelLines(page: Page) {
  return {
    block: page.getByText('רמות נוכחיות (להורה בלבד)'),
    reading: page.getByText(/קריאה:/),
    writing: page.getByText(/כתיבה:/),
  };
}

/** Число уровня из строки «קריאה: 5 / 10» / «כתיבה: 2 / 4». */
export function levelFromLine(text: string, scale: 10 | 4): number {
  const m = text.match(new RegExp(`(\\d+) \\/ ${scale}`));
  if (!m) throw new Error(`В строке «${text}» нет числа «N / ${scale}»`);
  return Number(m[1]);
}
